from hae.evaluation.harness import ExecutionHarness, SKIPPED, FAILED

def test_empty_workspace_smoke():
    harness = ExecutionHarness()
    # Create an empty workspace bundle
    empty_bundle = {}
    report = harness.verify_bundle(empty_bundle)
    smoke_gate = report.gate('smoke')
    if smoke_gate is None:
        print('ERROR: No smoke gate')
        return
    print(f'SMOKE_STATUS: {smoke_gate.status}')
    if smoke_gate.status == FAILED:
        print('CORRECT: Smoke failed on empty workspace')
    elif smoke_gate.status == SKIPPED:
        print('BUG: Smoke skipped on empty workspace')
    else:
        print(f'UNEXPECTED: {smoke_gate.status}')

if __name__ == '__main__':
    test_empty_workspace_smoke()

